INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('reading', '{"text": "Umbrellas are one of the oldest tools people use to stay dry in the rain. Early versions were made from paper and bamboo, while modern umbrellas use lightweight metal frames and waterproof fabric. Some umbrellas fold small enough to fit in a bag or pocket. Despite simple technology, a good umbrella can make a big difference on a stormy day."}'::jsonb, '{"exact": "Umbrellas are one of the oldest tools people use to stay dry in the rain. Early versions were made from paper and bamboo, while modern umbrellas use lightweight metal frames and waterproof fabric. Some umbrellas fold small enough to fit in a bag or pocket. Despite simple technology, a good umbrella can make a big difference on a stormy day."}'::jsonb, 64, 0.40, 'B1', 'approved', 'exam', 'weather', 'b4000000-0000-4000-8000-000000000011', 1),
('reading', '{"text": "Farmers markets have become popular in many cities around the world. They allow local farmers to sell fruits, vegetables, and other products directly to customers. Shoppers often prefer farmers markets because the food is fresher and sometimes cheaper than in large supermarkets. Many markets also sell homemade bread, cheese, and other local specialties."}'::jsonb, '{"exact": "Farmers markets have become popular in many cities around the world. They allow local farmers to sell fruits, vegetables, and other products directly to customers. Shoppers often prefer farmers markets because the food is fresher and sometimes cheaper than in large supermarkets. Many markets also sell homemade bread, cheese, and other local specialties."}'::jsonb, 55, 0.43, 'B1', 'approved', 'exam', 'shopping', 'b4000000-0000-4000-8000-000000000011', 2);
