INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('typing', '{"text": "Many people struggle to manage their time effectively, especially when juggling work, family, and personal interests. One helpful strategy is to prioritize tasks each morning, focusing first on the most important or urgent items. Breaking large projects into smaller steps can also make them feel less overwhelming and easier to start. Setting specific times for checking email and messages, rather than responding constantly throughout the day, can help maintain focus on bigger tasks. While no single method works perfectly for everyone, experimenting with a few simple techniques often leads to noticeable improvements in both productivity and overall stress levels."}'::jsonb, '{"exact": "Many people struggle to manage their time effectively, especially when juggling work, family, and personal interests. One helpful strategy is to prioritize tasks each morning, focusing first on the most important or urgent items. Breaking large projects into smaller steps can also make them feel less overwhelming and easier to start. Setting specific times for checking email and messages, rather than responding constantly throughout the day, can help maintain focus on bigger tasks. While no single method works perfectly for everyone, experimenting with a few simple techniques often leads to noticeable improvements in both productivity and overall stress levels."}'::jsonb, 95, 0.47, 'B1', 'approved', 'exam', 'business', 'b4000000-0000-4000-8000-000000000015', 1);
