INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('passage_reconstruction', '{"passage": "Omar forgot his umbrella before leaving for the market. Halfway there, dark clouds gathered and it began to rain steadily. He quickly found shelter under a shop''s awning. After twenty minutes, the rain eased, and he continued on, only slightly damp."}'::jsonb, '{"key_points": ["Omar forgot his umbrella", "it started raining heavily", "he sheltered under an awning", "he continued on only slightly damp"]}'::jsonb, 40, 0.50, 'B1', 'approved', 'exam', 'weather', 'b4000000-0000-4000-8000-000000000018', 1),
('passage_reconstruction', '{"passage": "Clara had been preparing a business proposal for weeks. During the meeting, investors asked several difficult questions about costs. She answered calmly using data she had prepared in advance. By the end, the investors agreed to fund her project."}'::jsonb, '{"key_points": ["Clara prepared a proposal for weeks", "investors asked difficult questions about costs", "she answered calmly with prepared data", "the investors agreed to fund the project"]}'::jsonb, 37, 0.54, 'B2', 'approved', 'exam', 'business', 'b4000000-0000-4000-8000-000000000018', 2),
('passage_reconstruction', '{"passage": "A local market recently started allowing vendors to accept card payments instead of only cash. At first, only a handful of stalls had the right equipment installed. Within a few months, nearly every vendor had adopted it, and customers found shopping there much more convenient."}'::jsonb, '{"key_points": ["the market started allowing card payments", "few stalls had the equipment at first", "most vendors adopted it within months", "shopping became more convenient"]}'::jsonb, 44, 0.55, 'B2', 'approved', 'exam', 'shopping', 'b4000000-0000-4000-8000-000000000018', 3);
INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('summary_and_opinion', '{"passage": "In recent years, some companies around the world have experimented with a four-day work week instead of the traditional five-day schedule. Employees work slightly longer hours on the days they do work, but they gain an extra day off each week. This idea has sparked significant discussion among business leaders, employees, and researchers.\n\nSupporters of the four-day work week argue that it improves employee wellbeing by giving workers more time to rest, spend with family, or pursue personal interests. Several companies that have trialed the policy report that employees return to work feeling more refreshed and motivated. Some studies also suggest that productivity does not necessarily decrease, and in some cases, it even improves, because employees feel less exhausted and more focused during their working days.\n\nOn the other hand, critics worry that a four-day work week may not suit every industry, particularly those that require constant staffing, such as hospitals or customer service centers. They also point out that longer working days can be exhausting, potentially cancelling out some of the wellbeing benefits. Additionally, some companies fear that reduced availability could frustrate clients who expect quick responses throughout the standard work week.\n\nOverall, the four-day work week appears to offer real benefits for certain types of jobs and industries, while posing practical challenges for others. Whether it becomes a widespread standard likely depends on how well companies can adapt their operations and whether the benefits to employee wellbeing continue to outweigh any drawbacks over time."}'::jsonb, '{"key_points": ["some companies trial a four-day work week", "supporters say it improves wellbeing without hurting productivity", "critics say it does not suit every industry and can frustrate clients", "adoption depends on how well companies adapt"]}'::jsonb, 277, 0.60, 'B2', 'approved', 'exam', 'business', 'b4000000-0000-4000-8000-000000000019', 1);
